        vm.assume(amount == 10 ether);
        vm.assume(blockNum > 0);
        vm.roll(blockNum);
        vm.warp(1);

        address sender = address(0x1234);
        vm.deal(sender, 20 ether);

        // First call
        vm.prank(sender);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // Second call in the same block
        vm.prank(sender);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

