pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp) public {
        // Use a timestamp that supports two consecutive calls in the same block:
        // first call succeeds and sets pastBlockTime = timestamp + 1;
        // the second call uses the same timestamp and must fail on the reference.
        vm.warp(timestamp);
        vm.roll(1); // not a multiple of 15 to avoid self-destruction / balance transfer complications

        address caller = address(0x1234);
        vm.deal(caller, 20 ether);

        // First call: should succeed and set pastBlockTime = timestamp + 1
        vm.prank(caller);
        (bool ok1, ) = address(c).call{value: 10 ether}("");

        // Second call: same timestamp, same block
        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // Reference requires strict > so second call fails; bug allows >= so second call succeeds.
        // The property we check: if the first call succeeded, the second call must fail.
        assertTrue(!(ok1 && ok2));
    }
}

