pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 blockNumber1, uint128 blockNumber2, uint64 timestamp1, uint64 timestamp2, address actor) public {
        vm.assume(blockNumber2 >= blockNumber1);
        vm.assume(timestamp2 >= timestamp1);
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);

        // First call
        vm.roll(blockNumber1);
        vm.warp(timestamp1);
        vm.deal(actor, 20 ether);
        vm.prank(actor);
        (bool success1, ) = address(c).call{value: 10 ether}("");
        vm.assume(success1); // only admissible when first call succeeds

        // Record balance after first call
        uint256 balanceAfterFirst = address(c).balance;

        // Second call in potentially same timestamp
        vm.roll(blockNumber2);
        vm.warp(timestamp2);
        vm.prank(actor);
        (bool success2, ) = address(c).call{value: 10 ether}("");

        // If the second call succeeds, the mutant must have executed past the removed require.
        // After a successful second call, the contract balance must be exactly 0 (because the transfer in fallback sent the entire balance to the actor).
        // The reference would have reverted on the require, so the balance would remain balanceAfterFirst.
        // The rule: if success2 is true, address(c).balance == 0.
        assertTrue(!success2 || address(c).balance == 0);
    }
}

