import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 fuzz_timestamp, uint128 fuzz_blockNumber) public {
        // Ensure block timestamp is at least 1 and block number is reasonable
        vm.assume(fuzz_timestamp >= 1);
        vm.assume(fuzz_blockNumber >= 1);

        // Warp to the fuzzed timestamp and roll to the fuzzed block number
        vm.warp(fuzz_timestamp);
        vm.roll(fuzz_blockNumber);

        // Record the block timestamp before the fallback call
        uint256 timestampBefore = block.timestamp;

        // Fund an EOA to send the required 10 ether
        address caller = address(0xBEEF);
        vm.deal(caller, 10 ether);

        // Execute the fallback call
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}("");
