pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 warpTime, bool useBlockMultiple15) public {
        // Ensure warpTime is in the future and not too large, keep domain wide
        vm.assume(warpTime > 0);
        vm.assume(warpTime <= type(uint64).max); // reasonable timestamp bound

        // Set block.timestamp to a known value
        vm.warp(warpTime);
        if (useBlockMultiple15) {
            // Ensure block.number is a multiple of 15 to trigger the transfer condition if needed by property
            vm.roll(block.number + (15 - (block.number % 15)));
        } else {
            // Ensure block.number is NOT a multiple of 15 to avoid transfer interference
            uint256 remainder = block.number % 15;
            if (remainder == 0) {
                vm.roll(block.number + 1);
            }
        }

        // Record pastBlockTime before call
        uint256 preTime = c.pastBlockTime();

        // Prepare actor with required 10 ether
        address actor = makeAddr("actor");
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "fallback call failed");

        // Record pastBlockTime after call
        uint256 postTime = c.pastBlockTime();

        // Universal property: pastBlockTime must strictly increase compared to its previous value
        assertTrue(postTime > preTime);
    }
}

