pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber) public {
        // Restrict to block numbers where the payout condition triggers (multiple of 15)
        // and a subsequent call can be made in the same block
        blockNumber = bound(blockNumber, 15, type(uint256).max - 1);
        vm.assume(blockNumber % 15 == 0);

        // Set up actor with enough ether
        address actor = address(0x1234);
        vm.deal(actor, 30 ether);

        // First call: set block number and warp to a timestamp such that first call succeeds
        vm.roll(blockNumber);
        vm.warp(1000);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        uint256 balanceAfterFirst = address(c).balance;

        // Same block, timestamp unchanged; second call
        vm.warp(1000); // same timestamp
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        uint256 balanceAfterSecond = address(c).balance;

        // The correct contract only allows one call per block (pastBlockTime = timestamp+1),
        // so the second call would fail, and balance would remain as after first.
        // The mutant allows a second call (pastBlockTime = timestamp),
        // so both calls succeed. Since both are on multiples of 15, both trigger payout,
        // draining the contract on the second call. Hence the balance diverges.
        assertTrue(balanceAfterFirst == balanceAfterSecond);
    }
}

